-- Migration 244: Cập nhật template WOKA — dùng field type "rows" (bảng chi phí động).
-- Schema mới: 1 field type=rows với 5 cột (nội dung, sl, đvt, đơn giá, thành tiền);
-- các field tổng (thành_tiền/VAT/tổng_cộng) có formula tự tính; user có thể thêm dòng.
UPDATE email_templates
SET
  subject_tpl = 'Đề nghị thanh toán {{ky_thue}} - HĐ {{so_hd}}',
  schema = '[
    {"key":"khach_hang","label":"Khách hàng","type":"text","required":true},
    {"key":"so_hd","label":"Số hợp đồng","type":"text","required":true,"default":"1203/2025/HDTN/161.1CH-WK"},
    {"key":"so_vb","label":"Số văn bản","type":"text","required":true},
    {"key":"ngay_lap","label":"Ngày lập","type":"date","required":true},
    {"key":"ky_thue","label":"Kỳ thuê","type":"text","required":true,"default":"Tháng 06/2026"},
    {"key":"line_items","label":"Chi tiết chi phí","type":"rows","columns":[
      {"key":"noi_dung","label":"Nội dung","type":"text"},
      {"key":"sl","label":"SL","type":"number","default":1},
      {"key":"dvt","label":"Đvt","type":"text","default":"Tháng"},
      {"key":"don_gia","label":"Đơn giá","type":"money"},
      {"key":"thanh_tien","label":"Thành tiền","type":"money","formula":"sl * don_gia"}
    ],"defaultRows":[
      {"noi_dung":"Tiền thuê","sl":1,"dvt":"Tháng","don_gia":23000000},
      {"noi_dung":"Phí quản lý","sl":1,"dvt":"Tháng","don_gia":500000},
      {"noi_dung":"Tiền gửi xe","sl":11,"dvt":"Xe","don_gia":150000},
      {"noi_dung":"Tiền điện","sl":0,"dvt":"kWh","don_gia":4000},
      {"noi_dung":"Tiền nước","sl":0,"dvt":"m³","don_gia":25000}
    ]},
    {"key":"thanh_tien_tong","label":"Thành tiền","type":"money","formula":"SUM(line_items.thanh_tien)"},
    {"key":"vat","label":"VAT 10%","type":"money","formula":"thanh_tien_tong * 0.1"},
    {"key":"tong_cong","label":"Tổng cộng","type":"money","formula":"thanh_tien_tong + vat"},
    {"key":"bang_chu","label":"Bằng chữ","type":"textarea","required":true},
    {"key":"han_tt","label":"Hạn thanh toán","type":"date","required":true},
    {"key":"noi_dung_ck","label":"Nội dung CK","type":"text","required":true}
  ]'::jsonb,
  body_html_tpl = '<!DOCTYPE html><html lang="vi"><body style="margin:0;padding:0;background:#eef0f3;font-family:Arial,Helvetica,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:28px 12px;"><table width="600" cellpadding="0" cellspacing="0" style="background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 2px 14px rgba(20,40,60,.08);"><tr><td style="background:#14263a;padding:26px 34px;color:#fff;"><div style="font-size:19px;font-weight:bold;">CÔNG TY CỔ PHẦN WOKA VIỆT NAM</div><div style="color:#9fb3c8;font-size:11px;margin-top:4px;">MST: 0317389240</div><div style="border-top:2px solid #b78a3f;width:44px;margin:14px 0;"></div><div style="font-size:22px;font-weight:bold;letter-spacing:1px;">ĐỀ NGHỊ THANH TOÁN</div><div style="color:#9fb3c8;font-size:12px;margin-top:6px;">Số: {{so_vb}} • TP. Hồ Chí Minh, ngày {{ngay_lap}}</div></td></tr><tr><td style="padding:26px 34px;color:#2d3b48;font-size:14px;line-height:1.6;"><p>Kính gửi: <strong style="color:#14263a;">{{khach_hang}}</strong>,</p><p>Căn cứ Hợp đồng thuê số <strong>{{so_hd}}</strong>, Công ty Cổ phần WOKA Việt Nam chân thành cảm ơn Quý Công ty đã tin tưởng sử dụng dịch vụ.</p><p>Chúng tôi kính đề nghị Quý Công ty thanh toán chi phí thuê kỳ <strong>{{ky_thue}}</strong> với chi tiết như sau:</p></td></tr><tr><td style="padding:0 34px;"><table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;"><tr><td style="background:#14263a;color:#fff;font-size:11px;font-weight:bold;padding:10px;">NỘI DUNG</td><td style="background:#14263a;color:#fff;font-size:11px;font-weight:bold;padding:10px;text-align:center;">SL</td><td style="background:#14263a;color:#fff;font-size:11px;font-weight:bold;padding:10px;text-align:center;">ĐVT</td><td style="background:#14263a;color:#fff;font-size:11px;font-weight:bold;padding:10px;text-align:right;">ĐƠN GIÁ</td><td style="background:#14263a;color:#fff;font-size:11px;font-weight:bold;padding:10px;text-align:right;">THÀNH TIỀN</td></tr>{{#line_items}}<tr><td style="border-bottom:1px solid #e6e9ee;padding:11px 10px;font-size:13px;">{{noi_dung}}</td><td style="border-bottom:1px solid #e6e9ee;padding:11px 10px;font-size:13px;text-align:center;">{{sl}}</td><td style="border-bottom:1px solid #e6e9ee;padding:11px 10px;font-size:13px;text-align:center;">{{dvt}}</td><td style="border-bottom:1px solid #e6e9ee;padding:11px 10px;font-size:13px;text-align:right;">{{fmt:money don_gia}}</td><td style="border-bottom:1px solid #e6e9ee;padding:11px 10px;font-size:13px;text-align:right;font-weight:bold;">{{fmt:money thanh_tien}}</td></tr>{{/line_items}}<tr><td colspan="4" style="padding:10px;text-align:right;font-size:13px;">Thành tiền</td><td style="padding:10px;text-align:right;font-size:13px;font-weight:bold;">{{fmt:money thanh_tien_tong}}</td></tr><tr><td colspan="4" style="padding:6px 10px;text-align:right;font-size:13px;">Thuế GTGT 10%</td><td style="padding:6px 10px;text-align:right;font-size:13px;font-weight:bold;">{{fmt:money vat}}</td></tr><tr><td colspan="4" style="background:#14263a;padding:14px 10px;text-align:right;color:#fff;font-size:14px;font-weight:bold;">TỔNG CỘNG</td><td style="background:#14263a;padding:14px 10px;text-align:right;color:#e9c986;font-size:17px;font-weight:bold;">{{fmt:money tong_cong}}</td></tr></table></td></tr><tr><td style="padding:8px 34px 4px;font-size:12.5px;font-style:italic;color:#5a6874;">Bằng chữ: {{bang_chu}}.</td></tr><tr><td style="padding:18px 34px 4px;"><table width="100%" cellpadding="0" cellspacing="0" style="background:#fbf3e6;border-left:4px solid #b78a3f;border-radius:4px;"><tr><td style="padding:12px 16px;color:#7a5a1e;font-size:13px;">⏱ Thời hạn thanh toán: <strong>chậm nhất ngày {{han_tt}}</strong></td></tr></table></td></tr><tr><td style="padding:14px 34px;"><table width="100%" cellpadding="0" cellspacing="0" style="background:#f5f7f9;border:1px solid #e2e7ec;border-radius:6px;"><tr><td style="padding:16px 18px;font-size:13px;color:#2d3b48;"><p style="margin:0 0 10px;color:#14263a;font-size:12px;font-weight:bold;text-transform:uppercase;">Thông tin chuyển khoản</p><table width="100%"><tr><td style="padding:3px 0;width:130px;color:#6b7883;">Chủ tài khoản</td><td style="padding:3px 0;font-weight:bold;">CÔNG TY CỔ PHẦN WOKA VIỆT NAM</td></tr><tr><td style="padding:3px 0;color:#6b7883;">Số tài khoản</td><td style="padding:3px 0;font-weight:bold;">1036907401</td></tr><tr><td style="padding:3px 0;color:#6b7883;">Ngân hàng</td><td style="padding:3px 0;">Vietcombank (TMCP Ngoại Thương Việt Nam) - CN Cộng Hòa</td></tr><tr><td style="padding:3px 0;color:#6b7883;">Nội dung CK</td><td style="padding:3px 0;">{{noi_dung_ck}}</td></tr></table></td></tr></table></td></tr><tr><td style="padding:20px 34px 6px;color:#2d3b48;font-size:13.5px;">Trân trọng cảm ơn sự hợp tác của Quý Công ty.</td></tr><tr><td style="background:#14263a;padding:20px 34px;color:#fff;font-size:11px;line-height:1.7;"><div style="font-size:13px;font-weight:bold;margin-bottom:4px;">CÔNG TY CỔ PHẦN WOKA VIỆT NAM</div>MST: 0317389240<br>Địa chỉ: (cập nhật địa chỉ)<br>☎ (số điện thoại) • ✉ (email)</td></tr></table></td></tr></table></body></html>',
  updated_at = NOW()
WHERE key = 'payment_woka';
